		// A plain stylesheet import is side-effect only outside the browser.
		return createDataUriModule(`export default undefined;`);
	}
	if (KNOWN_ASSET_RE.test(specifier)) {
		return createDataUriModule(`export default "";`);
	}
	return undefined;
